      className={cn(
        "inline-flex items-center rounded-md px-2 py-0.5",
        "text-xs font-medium ring-1 ring-inset",
        DELIVERY_STYLES[status],
      )}
    >
      {status.toLowerCase()}
    </span>
  );
}

